CREATE TABLE relay_wonderland.gve_runs(run_id text PRIMARY KEY,version text NOT NULL,policy_version text NOT NULL,project_id text NOT NULL REFERENCES relay_wonderland.projects,mission_id text NOT NULL REFERENCES relay_wonderland.mission_contracts,battle_id text REFERENCES relay_wonderland.battles,execution_id text NOT NULL REFERENCES relay_wonderland.execution_sessions,agent_id text NOT NULL REFERENCES relay_wonderland.agents,category text NOT NULL CHECK(category IN('VISIBLE_TESTS','HIDDEN_TESTS','ADVERSARIAL','ROBUSTNESS','SECURITY','PERFORMANCE','REGRESSION')),adapter_id text NOT NULL,adapter_version text NOT NULL,configuration_hash text NOT NULL,status text NOT NULL CHECK(status IN('QUEUED','RUNNING','PASSED','FAILED','UNAVAILABLE','ERROR')),queued_at timestamptz NOT NULL,started_at timestamptz,completed_at timestamptz,evidence_ids jsonb NOT NULL DEFAULT '[]',artifact_ids jsonb NOT NULL DEFAULT '[]',measurements jsonb NOT NULL DEFAULT '{}',failure text,score_eligible boolean NOT NULL DEFAULT false,snapshot jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),CHECK(NOT score_eligible OR status IN('PASSED','FAILED')));
CREATE INDEX wonderland_gve_recovery ON relay_wonderland.gve_runs(status,queued_at);
CREATE INDEX wonderland_gve_battle ON relay_wonderland.gve_runs(battle_id,category,status);
